static unsigned transform(unsigned x) {
  unsigned a = x * 17u + 13u;
  unsigned b = (a ^ (x >> 2)) * 7u;
  unsigned c = (b + 29u) ^ (a >> 1);
  return c + (x * x);
}

unsigned public_caller(unsigned x) {
  unsigned first = transform(x);
  unsigned second = transform(x + 1u);
  return first ^ (second + 3u);
}

